using System;
using System.Collections.Generic;
using System.Linq;
using AICad.Contracts;
using Newtonsoft.Json.Linq;
namespace AICad.Geometry;
public sealed class SectionResult {public List<Operation> Operations {get;}=new();public List<string> Notes {get;}=new();public Dictionary<string,double> Measurements {get;}=new();}
public static class ArchitectureBuilder {
 public static readonly string[] Builders={"STAIR_SECTION","WC_SECTION","BUILDING_SECTION","WC_DETAIL"};
 public static SectionResult Build(string kind,JObject input,double sourceWidth,double sourceDepth){if(!Builders.Contains(kind))throw new CadException("UNSUPPORTED_SKILL",kind);if(input.Value<bool?>("confirmed")!=true)throw new CadException("NEEDS_INPUT","Confirm architectural dimensions explicitly.");if(sourceWidth<=0||sourceDepth<=0)throw new CadException("NEEDS_SOURCE","A non-degenerate DWG source outline is required.");double N(string name,double min,double max){var token=input[name];if(token?.Type!=JTokenType.Integer&&token?.Type!=JTokenType.Float)throw new CadException("NEEDS_INPUT","Missing confirmed dimension: "+name);double value=token!.Value<double>();Validation.Finite(value);if(value<min||value>max)throw new CadException("INVALID_INPUT",name+" is outside supported range.");return value;}
 var result=new SectionResult();var ops=result.Operations;void Line(double x0,double y0,double x1,double y1,string layer="A-WALL")=>ops.Add(new(){Kind="draw_line",Layer=layer,Points=new(){new(x0,y0),new(x1,y1)}});void Text(double x,double y,string text)=>ops.Add(new(){Kind="add_text",Layer="A-TEXT",Height=100,Text=text,Points=new(){new(x,y)}});void Dim(double x0,double y0,double x1,double y1,double x2,double y2)=>ops.Add(new(){Kind="add_dimension",Layer="A-DIM",Points=new(){new(x0,y0),new(x1,y1),new(x2,y2)}});void Slab(double x,double y,double width,double thick){var box=Validation.Box(x,y-thick,x+width,y).ToList();ops.Add(new(){Kind="draw_polyline",Layer="A-WALL",Closed=true,Points=box});ops.Add(new(){Kind="create_hatch",Layer="A-HATCH",Closed=true,Points=box,Pattern="ANSI31",PatternScale=80});}
 double origin=1200,baseline=1200;
 if(kind=="STAIR_SECTION"){
  double height=N("floorHeight",1000,6000),riser=N("riser",80,250),tread=N("tread",150,500),landing=N("landing",500,3000),width=N("flightWidth",500,3000),slab=N("slabThickness",50,500);int count=(int)N("risers",4,40);if(count!=input.Value<double>("risers")||count%2!=0||Math.Abs(count*riser-height)>.1)throw new CadException("CONFLICTING_INPUT","Riser count/height must be consistent and split evenly into two flights.");int perFlight=count/2;double run=(perFlight-1)*tread;
  // The source outline is the unfolded stair footprint: run + landing + run.
  double expected=2*run+landing;if(Math.Abs(sourceWidth-expected)>1||Math.Abs(sourceDepth-width)>1)throw new CadException("SOURCE_MISMATCH","DWG stair outline must measure "+expected+" × "+width+" mm for the confirmed flight data.");
  var first=new List<Point2>{new(origin,baseline)};double x=origin,y=baseline;for(int i=0;i<perFlight;i++){y+=riser;first.Add(new(x,y));if(i<perFlight-1){x+=tread;first.Add(new(x,y));}}ops.Add(new(){Kind="draw_polyline",Layer="A-STAIR",Points=first});Slab(x,y,landing,slab);x+=landing;var second=new List<Point2>{new(x,y)};for(int i=0;i<perFlight;i++){y+=riser;second.Add(new(x,y));if(i<perFlight-1){x+=tread;second.Add(new(x,y));}}ops.Add(new(){Kind="draw_polyline",Layer="A-STAIR",Points=second});Slab(origin-300,baseline,600,slab);Slab(x,baseline+height,700,slab);Line(origin,baseline-slab,origin+run,baseline+height/2-slab);Line(origin+run+landing,baseline+height/2-slab,x,baseline+height-slab);Dim(origin-500,baseline,origin-500,baseline+height,origin-700,baseline+height/2);Dim(origin,baseline,origin+run,baseline,origin+run/2,baseline-500);Text(origin,baseline+height+600,"STAIR SECTION / SOURCE + CONFIRMED INPUTS");Text(origin,baseline-850,count+" risers x "+riser+" / tread "+tread+" / width "+width);Text(origin+run+100,baseline+height/2+250,"+"+(height/2/1000).ToString("0.000",System.Globalization.CultureInfo.InvariantCulture));result.Measurements["height"]=height;result.Measurements["run"]=run;result.Measurements["risers"]=count;result.Measurements["landing"]=landing;
 }else if(kind=="WC_SECTION"||kind=="WC_DETAIL"){
  double height=N("ceilingHeight",1800,4000),slab=N("slabThickness",50,500),tile=N("tileHeight",500,4000),waterproof=N("waterproofUpstand",100,1000);if(tile>height)throw new CadException("CONFLICTING_INPUT","Tile height exceeds room height.");double width=sourceWidth;Slab(origin,baseline,width,slab);Line(origin,baseline,origin,baseline+height);Line(origin+width,baseline,origin+width,baseline+height);Line(origin,baseline+height,origin+width,baseline+height);Line(origin+40,baseline,origin+40,baseline+waterproof,"A-HATCH");Line(origin+width-40,baseline,origin+width-40,baseline+waterproof,"A-HATCH");Line(origin,baseline+tile,origin+width,baseline+tile,"A-FLOOR");Dim(origin,baseline,origin+width,baseline,origin+width/2,baseline-500);Dim(origin+width,baseline,origin+width,baseline+height,origin+width+500,baseline+height/2);Text(origin,baseline+height+500,"WC SECTION / CONFIRMED ASSEMBLY");Text(origin,baseline-850,"Waterproof upstand "+waterproof+" / slab "+slab+" mm");result.Measurements["width"]=width;result.Measurements["ceilingHeight"]=height;
 }else{
  double floor=N("floorHeight",1800,6000),slab=N("slabThickness",50,500);int floors=(int)N("floors",1,5);if(floors!=input.Value<double>("floors"))throw new CadException("INVALID_INPUT","Whole floor count required.");for(int i=0;i<=floors;i++)Slab(origin,baseline+i*floor,sourceWidth,slab);Line(origin,baseline,origin,baseline+floors*floor);Line(origin+sourceWidth,baseline,origin+sourceWidth,baseline+floors*floor);for(int i=1;i<=floors;i++){Dim(origin+sourceWidth,baseline+(i-1)*floor,origin+sourceWidth,baseline+i*floor,origin+sourceWidth+500,baseline+(i-.5)*floor);Text(origin+200,baseline+i*floor+150,"LEVEL +"+(i*floor/1000).ToString("0.000",System.Globalization.CultureInfo.InvariantCulture));}Text(origin,baseline+floors*floor+600,"BUILDING SECTION / OUTLINE + CONFIRMED LEVELS");result.Measurements["floors"]=floors;result.Measurements["floorHeight"]=floor;
 }
 result.Notes.Add("Source outline and explicitly confirmed dimensions determine this section; hidden assemblies are not inferred.");return result;
 }
}
